async function mintDrop(ctx: ApiCtx): Promise<void> {
  const { res, deps, body, capability, secret } = ctx;
  if (!deps.keychain || !deps.secretDrops) return sendJson(res, 404, { error: "not_found" });
  if (!capability)
    return sendJson(res, 401, {
      error: "unauthorized",
      message: "secret-drop mint requires an agent capability token",
    });
  const capSecret = deps.capabilitySecret ?? secret;
  if (!capSecret)
    return sendJson(res, 500, { error: "misconfigured", message: "no capability secret to bind the drop link with" });
  if (capability.triggered) return sendJson(res, 403, { error: "forbidden", message: TRIGGERED });
  const b = body as {
    service?: unknown;
    envKey?: unknown;
    host?: unknown;
    purpose?: unknown;
    grantMode?: unknown;
    fields?: unknown;
  };
  if (typeof b.service !== "string" || !b.service.trim() || typeof b.purpose !== "string" || !b.purpose.trim()) {
    return sendJson(res, 400, {
      error: "bad_request",
      message: "expected { service, purpose, envKey?, host?, grantMode?, fields? }",
    });
  }
  if (b.grantMode !== undefined && b.grantMode !== "once" && b.grantMode !== "standing") {
    return sendJson(res, 400, { error: "bad_request", message: 'grantMode must be "once" or "standing"' });
  }
  const fields = parseDropFields(b.fields);
  if (fields === "invalid") {
    return sendJson(res, 400, {
      error: "bad_request",
      message: `fields must be 1–${MAX_DROP_FIELDS} items of { key: ENV_VAR_NAME, label?, secret? } with unique keys`,
    });
  }
  const scope = parseScopeId(capability.scopeId);
  const wantsGrant = scope.kind === "channel" || scope.kind === "group";
  const dest = resolveCapabilityDestination(capability, undefined);
  const { dropId } = await deps.secretDrops.mint({
    ownerId: capability.actorId,
    orgId: configOrgId(),
    service: b.service.trim(),
    ...(typeof b.envKey === "string" && b.envKey.trim() ? { envKey: b.envKey.trim() } : {}),
    ...(typeof b.host === "string" && b.host.trim() ? { host: b.host.trim() } : {}),
    ...(fields ? { fields } : {}),
    purpose: b.purpose.trim(),
    requestedBy: capability.actorId,
    audienceScopeId: capability.scopeId,
    ...(wantsGrant ? { grantMode: (b.grantMode as GrantMode | undefined) ?? "standing" } : {}),
    ...(wantsGrant && capability.scopeVersion ? { scopeVersion: capability.scopeVersion } : {}),
    ...(dest.ok && dest.destination ? { destination: dest.destination } : {}),
    ...(capability.threadRef ? { threadRef: capability.threadRef } : {}),
    requiresToken: true,
  });
  audit(deps, {
    principalId: capability.actorId,
    action: "keychain.drop.mint",
    resource: `${b.service.trim()}:${dropId}`,
    scopeLabel: capability.scopeId,
  });
  const linkToken = await mintCapabilityToken(
    {
      actorId: capability.actorId,
      scopeId: capability.scopeId,
      aud: SECRET_DROP_AUD,
      drop: dropId,
      exp: Date.now() + SECRET_DROP_TTL_MS,
    },
    capSecret,
  );
  const formPath = `/drop/${dropId}/form?t=${encodeURIComponent(linkToken)}`;
  const base = (deps.portalUrl ?? deps.publicUrl)?.replace(/\/$/, "");
  return sendJson(res, 200, { dropId, formPath, url: base ? `${base}${formPath}` : formPath });
}

async function dropForm(ctx: ApiCtx): Promise<void> {
  const { res, deps, params, req } = ctx;
  const peeked = deps.secretDrops ? await deps.secretDrops.peek(params.id!) : ({ ok: false } as const);
  if (!peeked.ok) {
    res.writeHead(404, { "content-type": "text/html; charset=utf-8" });
    return void res.end(dropFormHtml(params.id!, null));
  }
  if (!(await dropLinkTokenOk(ctx, params.id!, peeked.rec))) {
    res.writeHead(404, { "content-type": "text/html; charset=utf-8" });
    return void res.end(dropFormHtml(params.id!, null));
  }
  if (!samePerson(req.headers["x-drop-owner"] as string | undefined, peeked.rec.ownerId)) {
    res.writeHead(403, { "content-type": "text/html; charset=utf-8" });
    return void res.end(dropNotYoursHtml());
  }
  const rec = {
    service: peeked.rec.service,
    purpose: peeked.rec.purpose,
    fields: peeked.rec.fields,
    createdAt: peeked.rec.createdAt,
  };
  res.writeHead(200, { "content-type": "text/html; charset=utf-8" });
  res.end(dropFormHtml(params.id!, rec));
}

async function redeemDrop(ctx: ApiCtx): Promise<void> {
  const { res, deps, body, params, req } = ctx;
  if (!deps.keychain || !deps.secretDrops) return sendJson(res, 404, { error: "not_found" });
  const { secret, values } = body as { secret?: unknown; values?: unknown };
  const peeked = await deps.secretDrops.peek(params.id!);
  if (!peeked.ok) {
    const message =
      peeked.reason === "expired"
        ? "this drop link has expired — ask the agent for a fresh one"
        : "this drop link is invalid or was already used — ask the agent for a fresh one";
    return sendJson(res, 404, { error: "not_found", message });
  }
  if (!(await dropLinkTokenOk(ctx, params.id!, peeked.rec))) {
    return sendJson(res, 404, {
      error: "not_found",
      message: "this drop link is invalid or was already used — ask the agent for a fresh one",
    });
  }
  if (!samePerson(req.headers["x-drop-owner"] as string | undefined, peeked.rec.ownerId)) {
    return sendJson(res, 403, {
      error: "forbidden",
      message: "sign in as the account owner to complete this credential drop",
    });
  }
  if (!(await dropScopeAuthorized(ctx, peeked.rec))) {
    await deps.secretDrops.redeem(params.id!).catch(() => null);
    return sendJson(res, 409, {
      error: "scope_changed",
      message: "conversation membership changed — ask the agent for a fresh link",
    });
  }
  const dropFieldDefs = peeked.rec.fields;
  let saveFields: Array<{ envKey: string; value: string; secret: boolean }> | undefined;
  if (dropFieldDefs?.length) {
    const vmap = (typeof values === "object" && values ? values : {}) as Record<string, unknown>;
    saveFields = [];
    for (const f of dropFieldDefs) {
      const v = vmap[f.key];
      if (typeof v !== "string" || !v.trim())
        return sendJson(res, 400, { error: "bad_request", message: `missing value for ${f.key}` });
      saveFields.push({ envKey: f.key, value: v.trim(), secret: f.secret !== false });
    }
  } else if (typeof secret !== "string" || !secret.trim()) {
    return sendJson(res, 400, { error: "bad_request", message: "expected { secret }" });
  }
  const redeemed = await deps.secretDrops.redeem(params.id!);
  if (!redeemed.ok) {
    const message =
      redeemed.reason === "expired"
        ? "this drop link has expired — ask the agent for a fresh one"
        : "this drop link is invalid or was already used — ask the agent for a fresh one";
    return sendJson(res, 404, { error: "not_found", message });
  }
  const drop = redeemed.rec;
  if (drop.orgId !== undefined && drop.orgId !== configOrgId())
    return sendJson(res, 404, { error: "not_found", message: "this drop link is for a different org" });
  try {
    const meta = await deps.keychain.save({
      ownerId: drop.ownerId,
      service: drop.service,
      ...(saveFields ? { fields: saveFields } : { secret: secret as string }),
      ...(!saveFields && drop.envKey ? { envKey: drop.envKey } : {}),
      ...(drop.host ? { host: drop.host } : {}),
      origin: "secret-drop",
    });
    const mayShare = await dropScopeAuthorized(ctx, drop);
    let grantId: string | undefined;
    if (mayShare && drop.grantMode && drop.audienceScopeId) {
      const grant = await deps.keychain.createGrant({
        credentialId: meta.id,
        ownerId: drop.ownerId,
        audienceScopeId: drop.audienceScopeId,
        mode: drop.grantMode,
        purpose: drop.purpose,
      });
      grantId = grant.id;
    }
    audit(deps, {
      principalId: drop.ownerId,
      action: "keychain.drop.redeem",
      resource: `${meta.service}:${meta.id}`,
      scopeLabel: drop.audienceScopeId ?? drop.ownerId,
    });
    if (mayShare && drop.audienceScopeId) {
      void (async () => {
        const pending = (await deps.secretDrops!.siblings(drop).catch(() => [])).map((s) => s.service);
        await deps.fireDropResolution?.({
          id: params.id!,
          ownerId: drop.ownerId,
          service: meta.service,
          purpose: drop.purpose,
          audienceScopeId: drop.audienceScopeId!,
          ...(drop.destination ? { destination: drop.destination } : {}),
          ...(drop.threadRef ? { threadRef: drop.threadRef } : {}),
          ...(grantId ? { grantId } : {}),
          granted: !!grantId,
          ...(pending.length ? { pendingSiblings: pending } : {}),
        });
      })().catch((e) => swallow("secret-drop: resolution fire failed", e));
    }
    return sendJson(res, 200, { ok: true, credential: meta });
  } catch (e) {
    if (e instanceof KeychainError) return sendJson(res, e.status, { error: "keychain", message: e.message });
    throw e;
  }
}

export const secretDropRoutes: ReadonlyArray<Route<ApiCtx>> = [
  { method: "POST", path: "/v1/keychain/drops", auth: "either", handle: mintDrop },
  { method: "GET", path: "/v1/keychain/drops/:id/form", auth: "source", handle: dropForm },
  { method: "POST", path: "/v1/keychain/drops/:id", auth: "source", handle: redeemDrop },
];

import { sendJson } from "../../http.ts";
import { audit, authorizeAdmin, orgScope } from "../shared.ts";
import type { ApiCtx } from "../route.ts";
import { errMessage } from "../../../util/errors.ts";
import { validateSlackInstallation } from "../../../surfaces/slack-installation.ts";
import { slackBotManifestCreationUrl } from "../../../surfaces/slack-manifest.ts";

export async function getSlackInstallation(ctx: ApiCtx): Promise<void> {
  const scope = orgScope(ctx.deps);
  const actor = await authorizeAdmin(ctx, scope);
  if (!actor) return;
  if (!ctx.deps.slackInstallation) return sendJson(ctx.res, 404, { error: "not_configured" });
  audit(ctx.deps, {
    principalId: actor.id,
    action: "slack-installation.read",
    resource: "slack-installation",
    scopeLabel: scope,
  });
  const createUrl = slackBotManifestCreationUrl();
  const stored = await ctx.deps.slackInstallation.status();
  if (stored.managed) return sendJson(ctx.res, 200, { ...stored, source: "admin", createUrl });
  if (ctx.deps.slackEnvironmentState === "configured") {
    return sendJson(ctx.res, 200, { configured: true, managed: false, source: "environment", createUrl });
  }
  return sendJson(ctx.res, 200, {
    configured: false,
    managed: false,
    source: ctx.deps.slackEnvironmentState === "partial" ? "invalid_environment" : "none",
    createUrl,
  });
}

export async function putSlackInstallation(ctx: ApiCtx): Promise<void> {
  const scope = orgScope(ctx.deps);
  const actor = await authorizeAdmin(ctx, scope);
  if (!actor) return;
  if (!ctx.deps.slackInstallation) return sendJson(ctx.res, 404, { error: "not_configured" });
  const body = ctx.body as { botToken?: unknown; appToken?: unknown };
  const botToken = typeof body.botToken === "string" ? body.botToken.trim() : "";
  const appToken = typeof body.appToken === "string" ? body.appToken.trim() : "";
  try {
    const workspace = await validateSlackInstallation(
      botToken,
      appToken,
      ctx.deps.slackInstallationFetch,
      ctx.deps.slackInstallationSocketAppId,
    );
    const status = await ctx.deps.slackInstallation.set({ botToken, appToken, ...workspace, updatedBy: actor.id });
    audit(ctx.deps, {
      principalId: actor.id,
      action: "slack-installation.update",
      resource: "slack-installation",
      scopeLabel: scope,
    });
    return sendJson(ctx.res, 200, { ...status, source: "admin" });
  } catch (error) {
    return sendJson(ctx.res, 400, { error: "invalid_slack_installation", message: errMessage(error) });
  }
}

export async function deleteSlackInstallation(ctx: ApiCtx): Promise<void> {
  const scope = orgScope(ctx.deps);
  const actor = await authorizeAdmin(ctx, scope);
  if (!actor) return;
  if (!ctx.deps.slackInstallation) return sendJson(ctx.res, 404, { error: "not_configured" });
  await ctx.deps.slackInstallation.delete(actor.id);
  audit(ctx.deps, {
    principalId: actor.id,
    action: "slack-installation.delete",
    resource: "slack-installation",
    scopeLabel: scope,
  });
  return sendJson(ctx.res, 200, { configured: false, managed: true, source: "admin" });
}

import { sendJson } from "../http.ts";
import { isObj } from "./shared.ts";
import { type ApiCtx, type Route } from "./route.ts";

const NAMESPACE = "authbroker:";
const MAX_IDS = 64;
const MAX_ID_LENGTH = 200;
const MAX_HORIZON_MS = 24 * 60 * 60 * 1000;

async function claimBrokerNonce(ctx: ApiCtx): Promise<void> {
  const { res, deps, body } = ctx;
  if (!deps.replayDedupe?.durable) {
    return sendJson(res, 503, {
      error: "not_configured",
      message:
        "single-use claims need the Postgres-backed replay store; set DATABASE_URL so a restart cannot resurrect a spent sign-in link",
    });
  }
  const b = isObj(body) ? body : {};
  const ids: unknown[] = Array.isArray(b.ids) ? b.ids : [];
  if (
    ids.length === 0 ||
    ids.length > MAX_IDS ||
    !ids.every((id) => typeof id === "string" && id.length > 0 && id.length <= MAX_ID_LENGTH)
  ) {
    return sendJson(res, 400, {
      error: "bad_request",
      message: `ids must hold 1 to ${MAX_IDS} non-empty strings of at most ${MAX_ID_LENGTH} characters`,
    });
  }
  const now = Date.now();
  const expiresAtMs = b.expiresAtMs;
  if (
    typeof expiresAtMs !== "number" ||
    !Number.isFinite(expiresAtMs) ||
    expiresAtMs <= now ||
    expiresAtMs > now + MAX_HORIZON_MS
  ) {
    return sendJson(res, 400, {
      error: "bad_request",
      message: "expiresAtMs must be a future epoch-millisecond timestamp within 24 hours",
    });
  }
  for (const id of ids as string[]) {
    if (await deps.replayDedupe.claim(`${NAMESPACE}${id}`, expiresAtMs)) return sendJson(res, 200, { claimed: id });
  }
  return sendJson(res, 200, { claimed: null });
}

export const authBrokerRoutes: ReadonlyArray<Route<ApiCtx>> = [
  { method: "POST", path: "/v1/auth/broker/claim", auth: "source", handle: claimBrokerNonce },
];

import { isStrongSigningSecret } from "../auth/source-auth.ts";

type SecretGate =
  | "production"
  | "codex"
  | "postgres"
  | "sprites"
  | "fly-sandbox"
  | "fly-deploy"
  | "aws-deploy-gate"
  | "google-oauth"
  | "dropbox-oauth"
  | "linear-oauth"
  | "model-anthropic"
  | "model-openai"
  | "model-openrouter";

export interface RuntimeSecretSpec {
  name: string;
  requiredWhen: SecretGate | readonly SecretGate[];
}

export const CORE_SECRET_SPECS: readonly RuntimeSecretSpec[] = [
  { name: "CAPABILITY_SECRET", requiredWhen: "production" },
  { name: "CONNECTOR_SECRET_KEY", requiredWhen: "production" },
  { name: "CORE_SIGNING_SECRET", requiredWhen: "production" },
  { name: "PORTAL_IDENTITY_SECRET", requiredWhen: "production" },
  { name: "SKILL_SIGNING_SECRET", requiredWhen: "production" },
  { name: "OPENAI_API_KEY", requiredWhen: ["codex", "model-openai"] },
  { name: "ANTHROPIC_API_KEY", requiredWhen: "model-anthropic" },
  { name: "OPENROUTER_API_KEY", requiredWhen: "model-openrouter" },
  { name: "DATABASE_URL", requiredWhen: "postgres" },
  { name: "SPRITES_TOKEN", requiredWhen: "sprites" },
  { name: "FLY_API_TOKEN", requiredWhen: "fly-sandbox" },
  { name: "FLY_DEPLOY_API_TOKEN", requiredWhen: "fly-deploy" },
  { name: "AWS_DEPLOY_GATE_SECRET", requiredWhen: "aws-deploy-gate" },
  { name: "GOOGLE_OAUTH_CLIENT_SECRET", requiredWhen: "google-oauth" },
  { name: "DROPBOX_OAUTH_CLIENT_SECRET", requiredWhen: "dropbox-oauth" },
  { name: "LINEAR_OAUTH_CLIENT_SECRET", requiredWhen: "linear-oauth" },
];

const GATE_PREDICATES: Readonly<Record<SecretGate, (env: NodeJS.ProcessEnv) => boolean>> = {
  production: (env) => env.NODE_ENV === "production",
  codex: (env) => env.HARNESS?.trim() === "codex",
  postgres: (env) => env.SESSION_STORE === "postgres" || env.RUN_STORE === "postgres",
  sprites: (env) => env.SANDBOX_BACKEND === "sprites" || env.SANDBOX_SECONDARY_BACKEND === "sprites",
  "fly-sandbox": (env) => env.SANDBOX_BACKEND === "fly",
  "fly-deploy": (env) => env.DEPLOY_PROVIDER === "fly",
  "aws-deploy-gate": (env) => Boolean(env.AWS_DEPLOY_APPS_DOMAIN),
  "google-oauth": (env) => Boolean(env.GOOGLE_OAUTH_CLIENT_ID),
  "dropbox-oauth": (env) => Boolean(env.DROPBOX_OAUTH_CLIENT_ID),
  "linear-oauth": (env) => Boolean(env.LINEAR_OAUTH_CLIENT_ID),
  "model-anthropic": (env) => env.MODEL_PROVIDER?.trim() === "anthropic",
  "model-openai": (env) => env.MODEL_PROVIDER?.trim() === "openai",
  "model-openrouter": (env) => env.MODEL_PROVIDER?.trim() === "openrouter",
};

export function validateCoreSecretEnv(env: NodeJS.ProcessEnv): string[] {
  const enabled = (spec: RuntimeSecretSpec): boolean => {
    const gates = typeof spec.requiredWhen === "string" ? [spec.requiredWhen] : spec.requiredWhen;
    return gates.some((gate) => GATE_PREDICATES[gate](env));
  };
  return CORE_SECRET_SPECS.filter((spec) => enabled(spec) && isInvalidSecret(spec.name, env[spec.name])).map(
    (spec) => spec.name,
  );
}

function isInvalidSecret(name: string, value: string | undefined): boolean {
  const candidate = value?.trim();
  if (!candidate || /^(replace-me|placeholder|changeme|todo)$/i.test(candidate)) return true;
  return (
    (name === "CONNECTOR_SECRET_KEY" || name === "CORE_SIGNING_SECRET" || name === "SKILL_SIGNING_SECRET") &&
    !isStrongSigningSecret(candidate)
  );
}

import type { Reach } from "../deploy/deploy-service.ts";
import { mintDeployGitAccess } from "../deploy/access-token.ts";

import type { App, AppDeps, ViewerDeployment } from "./app-types.ts";
import { deploymentView } from "./app-types.ts";
import type { AppHelpers } from "./app-helpers.ts";

export function createDeploymentMethods(
  deps: AppDeps,
  h: AppHelpers,
): Pick<
  App,
  | "deploy"
  | "redeploy"
  | "listDeployments"
  | "getDeployment"
  | "shareDeployment"
  | "deploymentGrantees"
  | "listDeploymentsForViewer"
  | "effectiveDeploymentPermission"
  | "deploymentGitPermissionFor"
  | "rollbackDeployment"
  | "canManageDeployment"
  | "archiveDeployment"
  | "restoreDeployment"
  | "renameDeployment"
  | "setDeploymentDisplayName"
  | "reachDeployment"
  | "deploymentGitRepoPath"
  | "runDeploymentGitPush"
  | "deploymentGitUrlFor"
  | "authorizesDeploymentGitAccess"
  | "reapIdleDeployments"
  | "listEnvironments"
  | "createEnvironment"
  | "resolveEnvironmentByName"
  | "attachScope"
> {
  const { effectiveDeploymentPermission, principalCanReadDeployment, principalGitPermission } = h;
  return {
    deploy(input) {
      return deps.deploy.deploy(input);
    },
    redeploy(id, input) {
      return deps.deploy.redeploy(id, input);
    },
    listDeployments() {
      return deps.deploy.listDeployments();
    },
    getDeployment(idOrName) {
      return deps.deploy.getDeployment(idOrName);
    },
    shareDeployment(idOrName, grantee, permission, actor) {
      return deps.deploy.shareDeployment(idOrName, grantee, permission, actor);
    },
    deploymentGrantees(idOrName) {
      return deps.deploy.deploymentGrantees(idOrName);
    },
    async listDeploymentsForViewer(principalId) {
      const deployments = await deps.deploy.listDeployments();
      const enriched = await Promise.all(
        deployments.map(async (d): Promise<ViewerDeployment | null> => {
          const permission = await principalGitPermission(d, principalId);
          return permission ? { ...deploymentView(d), permission } : null;
        }),
      );
      return enriched.filter((d): d is ViewerDeployment => d != null);
    },
    effectiveDeploymentPermission(d, principalId) {
      return effectiveDeploymentPermission(d, principalId);
    },
    async deploymentGitPermissionFor(idOrName, principalId) {
      const deployment = (await deps.deploy.listDeployments()).find((d) => d.id === idOrName || d.name === idOrName);
      return deployment ? principalGitPermission(deployment, principalId) : null;
    },
    rollbackDeployment(id, version) {
      return deps.deploy.rollbackDeployment(id, version);
    },
    canManageDeployment(idOrName, callerId, actingScopeId) {
      return deps.deploy.canManageDeployment(idOrName, callerId, actingScopeId);
    },
    archiveDeployment(id) {
      return deps.deploy.archiveDeployment(id);
    },
    restoreDeployment(id, actorId) {
      return deps.deploy.restoreDeployment(id, actorId);
    },
    renameDeployment(id, name) {
      return deps.deploy.renameDeployment(id, name);
    },
    setDeploymentDisplayName(id, displayName) {
      return deps.deploy.setDeploymentDisplayName(id, displayName);
    },
    async reachDeployment(id, principalId, opts): Promise<Reach> {
      if (opts?.bypassAcl) return deps.deploy.reachDeployment(id, principalId, opts);
      const deployment = await deps.deploy.getDeployment(id);
      if (!deployment) return { status: "not_found" };
      if (!(await principalCanReadDeployment(deployment, principalId))) return { status: "denied" };
      return deps.deploy.reachDeployment(id, principalId, { bypassAcl: true });
    },
    deploymentGitRepoPath(id) {
      return deps.deploy.gitRepoPath(id);
    },
    runDeploymentGitPush(id, runReceivePack) {
      return deps.deploy.pushGit(id, runReceivePack);
    },
    async deploymentGitUrlFor(idOrName, principalId, opts) {
      const d = await deps.deploy.getDeployment(idOrName);
      if (!d) return null;
      const permission = await principalGitPermission(d, principalId);
      if (!permission) return null;
      const token = await mintDeployGitAccess(opts.secret, {
        deploymentId: d.id,
        permission,
        principalId,
        exp: Date.now() + (opts.ttlMs ?? 60 * 60 * 1000),
      });
      const url = new URL(`/v1/deployments/${encodeURIComponent(d.id)}/git`, opts.baseUrl);
      url.username = "deployment";
      url.password = token;
      return { url: url.toString(), permission };
    },
    async authorizesDeploymentGitAccess(id, principalId, permission) {
      const d = await deps.deploy.getDeployment(id);
      if (!d) return false;
      const current = await principalGitPermission(d, principalId);
      return permission === "write" ? current === "write" : current !== null;
    },
    reapIdleDeployments(ttlMs, now) {
      return deps.deploy.reapIdleDeployments(ttlMs, now);
    },

    async listEnvironments() {
      if (!deps.environments) return [];
      const envs = await deps.environments.list();
      return Promise.all(
        envs.map(async (environment) => ({
          environment,
          attachments: await deps.environments!.attachmentsFor(environment.id),
        })),
      );
    },
    async createEnvironment(input) {
      if (!deps.environments) throw new Error("environments not wired");
      const env = await deps.environments.create({
        id: input.scopeId,
        name: input.name,
        ownerActorId: input.actorId,
      });
      deps.auditLog.record({
        at: Date.now(),
        principalId: input.actorId,
        action: "environment_create",
        resource: env.id,
        scopeLabel: input.scopeId,
      });
      return env;
    },
    resolveEnvironmentByName(name) {
      if (!deps.environments) return Promise.resolve(null);
      return deps.environments.list().then((envs) => envs.find((e) => e.name === name) ?? null);
    },
    async attachScope(input) {
      if (!deps.environments) throw new Error("environments not wired");
      await deps.environments.attach(input.scopeId, input.environmentId, input.actorId);
      deps.auditLog.record({
        at: Date.now(),
        principalId: input.actorId,
        action: "environment_attach",
        resource: input.environmentId,
        scopeLabel: input.scopeId,
      });
    },
  };
}

